SELECT s.customer_id, ROUND((100 * SUM(CASE WHEN we.page = '/home' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_home, ROUND((100 * SUM(CASE WHEN we.page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout FROM web_events we INNER JOIN sessions s ON we.session_id = s.id INNER JOIN customers c ON s.customer_id = c.id WHERE c.age < 48 GROUP BY s.customer_id ORDER BY pct_home DESC, customer_id LIMIT 5;
